package com.team.payment.controller;

import com.team.payment.dto.CreatePaymentRequest;
import com.team.payment.dto.HistoryResponse;
import com.team.payment.dto.PaymentListResponse;
import com.team.payment.dto.PaymentResponse;
import com.team.payment.service.PaymentService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.Valid;
import java.util.List;
import java.util.UUID;

/**
 * 支付REST API控制器
 */
@RestController
@RequestMapping("/api/payments")
@CrossOrigin(origins = "*")
public class PaymentController {

    @Autowired
    private PaymentService paymentService;

    /**
     * POST /api/payments
     * 创建支付
     * 成员A负责实现
     *
     * 请求头: Idempotency-Key: client-provided-key
     * 响应码: 201 Created (新建) / 200 OK (幂等重复) / 409 Conflict (幂等键冲突) / 400 Bad Request (校验失败)
     */
    @PostMapping
    public ResponseEntity<PaymentResponse> createPayment(
            @Valid @RequestBody CreatePaymentRequest request,
            @RequestHeader(value = "Idempotency-Key", required = true) String idempotencyKey) {

        PaymentResponse response = paymentService.createPayment(request, idempotencyKey);
        return new ResponseEntity<>(response, HttpStatus.CREATED);
    }

    /**
     * GET /api/payments/{id}
     * 查询支付详情
     * 成员C负责实现
     *
     * 响应码: 200 OK / 404 Not Found
     */
    @GetMapping("/{id}")
    public ResponseEntity<PaymentResponse> getPaymentDetail(@PathVariable Long id) {
        PaymentResponse response = paymentService.getPaymentDetail(id);
        return new ResponseEntity<>(response, HttpStatus.OK);
    }

    /**
     * GET /api/payments?status=CREATED&page=0&size=20
     * 列表查询（分页+筛选）
     * 成员C负责实现
     *
     * 查询参数:
     *   - status: 筛选状态（可选）
     *   - page: 页码（从0开始，默认0）
     *   - size: 页大小（默认20）
     *
     * 响应码: 200 OK
     */
    @GetMapping
    public ResponseEntity<PaymentListResponse> listPayments(
            @RequestParam(value = "status", required = false) String status,
            @RequestParam(value = "page", defaultValue = "0") int page,
            @RequestParam(value = "size", defaultValue = "20") int size) {

        PaymentListResponse response = paymentService.listPayments(page, size, status);
        return new ResponseEntity<>(response, HttpStatus.OK);
    }

    /**
     * GET /api/payments/{id}/history
     * 查询支付历史
     * 成员C负责实现
     *
     * 响应码: 200 OK / 404 Not Found
     */
    @GetMapping("/{id}/history")
    public ResponseEntity<List<HistoryResponse>> getPaymentHistory(@PathVariable Long id) {
        List<HistoryResponse> response = paymentService.getPaymentHistory(id);
        return new ResponseEntity<>(response, HttpStatus.OK);
    }

    /**
     * POST /api/payments/{id}/validate
     * 手动推进状态为VALIDATED（演示用）
     * 成员B负责实现
     *
     * 响应码: 200 OK / 404 Not Found / 400 Bad Request
     */
    @PostMapping("/{id}/validate")
    public ResponseEntity<PaymentResponse> validatePayment(@PathVariable Long id) {
        PaymentResponse response = paymentService.validatePayment(id);
        return new ResponseEntity<>(response, HttpStatus.OK);
    }

    /**
     * POST /api/payments/{id}/send
     * 手动推进状态为SENT（演示用）
     * 成员B负责实现
     *
     * 响应码: 200 OK / 404 Not Found / 400 Bad Request
     */
    @PostMapping("/{id}/send")
    public ResponseEntity<PaymentResponse> sendPayment(@PathVariable Long id) {
        PaymentResponse response = paymentService.sendPayment(id);
        return new ResponseEntity<>(response, HttpStatus.OK);
    }

    /**
     * POST /api/payments/{id}/complete
     * 手动推进状态为COMPLETED（演示用）
     * 成员B负责实现
     *
     * 响应码: 200 OK / 404 Not Found / 400 Bad Request
     */
    @PostMapping("/{id}/complete")
    public ResponseEntity<PaymentResponse> completePayment(@PathVariable Long id) {
        PaymentResponse response = paymentService.completePayment(id);
        return new ResponseEntity<>(response, HttpStatus.OK);
    }

    /**
     * POST /api/payments/{id}/fail
     * 手动推进状态为FAILED（演示用）
     * 成员B负责实现
     *
     * 请求体:
     * {
     *   "errorCode": "BUSINESS_ERROR",
     *   "errorMessage": "业务规则检查失败"
     * }
     *
     * 响应码: 200 OK / 404 Not Found / 400 Bad Request
     */
    @PostMapping("/{id}/fail")
    public ResponseEntity<PaymentResponse> failPayment(
            @PathVariable Long id,
            @RequestParam(value = "errorCode", defaultValue = "PROCESSING_ERROR") String errorCode,
            @RequestParam(value = "errorMessage", defaultValue = "Payment failed") String errorMessage) {

        PaymentResponse response = paymentService.failPayment(id, errorCode, errorMessage);
        return new ResponseEntity<>(response, HttpStatus.OK);
    }
}

package com.team.payment.dao;

import com.team.payment.entity.Payment;
import com.team.payment.entity.PaymentHistory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Objects;

/**
 * 支付DAO
 * 通过JDBC Template访问数据库
 */
@Repository
public class PaymentDao {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    /**
     * Payment RowMapper
     */
    private static final RowMapper<Payment> PAYMENT_ROW_MAPPER = (rs, rowNum) ->
        Payment.builder()
            .id(rs.getLong("id"))
            .idempotencyKey(rs.getString("idempotency_key"))
            .sourceAccount(rs.getString("source_account"))
            .destinationAccount(rs.getString("destination_account"))
            .amount(rs.getBigDecimal("amount"))
            .currency(rs.getString("currency"))
            .status(rs.getString("status"))
            .errorCode(rs.getString("error_code"))
            .errorMessage(rs.getString("error_message"))
            .reference(rs.getString("reference"))
            .version(rs.getLong("version"))
            .createdAt(rs.getObject("created_at", LocalDateTime.class))
            .updatedAt(rs.getObject("updated_at", LocalDateTime.class))
            .build();

    /**
     * 创建支付记录
     */
    @Transactional
    public Payment create(Payment payment) {
        String sql = "INSERT INTO payments (idempotency_key, source_account, destination_account, " +
                     "amount, currency, status, reference, version, created_at, updated_at) " +
                     "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";

        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbcTemplate.update(con -> {
            PreparedStatement ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, payment.getIdempotencyKey());
            ps.setString(2, payment.getSourceAccount());
            ps.setString(3, payment.getDestinationAccount());
            ps.setBigDecimal(4, payment.getAmount());
            ps.setString(5, payment.getCurrency());
            ps.setString(6, payment.getStatus());
            ps.setString(7, payment.getReference());
            ps.setLong(8, 0L);
            ps.setTimestamp(9, Timestamp.valueOf(LocalDateTime.now()));
            ps.setTimestamp(10, Timestamp.valueOf(LocalDateTime.now()));
            return ps;
        }, keyHolder);

        payment.setId(Objects.requireNonNull(keyHolder.getKey()).longValue());
        return payment;
    }

    /**
     * 根据ID查询支付
     */
    public Payment findById(Long id) {
        String sql = "SELECT * FROM payments WHERE id = ?";
        List<Payment> results = jdbcTemplate.query(sql, new Object[]{id}, PAYMENT_ROW_MAPPER);
        return results.isEmpty() ? null : results.get(0);
    }

    /**
     * 根据幂等键查询支付
     */
    public Payment findByIdempotencyKey(String idempotencyKey) {
        String sql = "SELECT * FROM payments WHERE idempotency_key = ?";
        List<Payment> results = jdbcTemplate.query(sql, new Object[]{idempotencyKey}, PAYMENT_ROW_MAPPER);
        return results.isEmpty() ? null : results.get(0);
    }

    /**
     * 分页查询支付（可选按状态筛选）
     */
    public List<Payment> findPaginated(int page, int size, String status) {
        String sql = "SELECT * FROM payments";
        Object[] params;

        if (status != null && !status.isEmpty()) {
            sql += " WHERE status = ?";
            params = new Object[]{status};
        } else {
            params = new Object[]{};
        }

        sql += " ORDER BY updated_at DESC LIMIT ? OFFSET ?";

        if (status != null && !status.isEmpty()) {
            Object[] newParams = new Object[3];
            newParams[0] = status;
            newParams[1] = size;
            newParams[2] = page * size;
            params = newParams;
        } else {
            params = new Object[]{size, page * size};
        }

        return jdbcTemplate.query(sql, params, PAYMENT_ROW_MAPPER);
    }

    /**
     * 统计支付记录数（可选按状态筛选）
     */
    public long countByStatus(String status) {
        String sql = "SELECT COUNT(*) FROM payments";
        Object[] params;

        if (status != null && !status.isEmpty()) {
            sql += " WHERE status = ?";
            params = new Object[]{status};
        } else {
            params = new Object[]{};
        }

        Long count = jdbcTemplate.queryForObject(sql, params, Long.class);
        return count != null ? count : 0L;
    }

    /**
     * 更新支付状态
     */
    @Transactional
    public int updateStatus(Long id, String newStatus, String errorCode, String errorMessage) {
        String sql = "UPDATE payments SET status = ?, error_code = ?, error_message = ?, " +
                     "version = version + 1, updated_at = ? WHERE id = ?";

        return jdbcTemplate.update(sql,
            newStatus,
            errorCode,
            errorMessage,
            Timestamp.valueOf(LocalDateTime.now()),
            id
        );
    }

    /**
     * 查询超时的支付（满N分钟未更新）
     */
    public List<Payment> findTimeoutPayments(String status, int timeoutMinutes) {
        String sql = "SELECT * FROM payments WHERE status = ? AND " +
                     "updated_at < DATE_SUB(NOW(), INTERVAL ? MINUTE)";
        return jdbcTemplate.query(sql, new Object[]{status, timeoutMinutes}, PAYMENT_ROW_MAPPER);
    }

    /**
     * 查询所有未完成的支付
     */
    public List<Payment> findUnfinishedPayments() {
        String sql = "SELECT * FROM payments WHERE status NOT IN ('COMPLETED', 'FAILED') " +
                     "ORDER BY updated_at ASC";
        return jdbcTemplate.query(sql, PAYMENT_ROW_MAPPER);
    }
}

package com.team.payment.dao;

import com.team.payment.entity.PaymentHistory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;

/**
 * 支付历史DAO
 * 成员C负责实现
 */
@Repository
public class PaymentHistoryDao {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    /**
     * PaymentHistory RowMapper
     */
    private static final RowMapper<PaymentHistory> HISTORY_ROW_MAPPER = (rs, rowNum) ->
        PaymentHistory.builder()
            .id(rs.getLong("id"))
            .paymentId(rs.getLong("payment_id"))
            .fromStatus(rs.getString("from_status"))
            .toStatus(rs.getString("to_status"))
            .reason(rs.getString("reason"))
            .triggeredBy(rs.getString("triggered_by"))
            .createdAt(rs.getObject("created_at", LocalDateTime.class))
            .build();

    /**
     * 插入历史记录
     */
    @Transactional
    public PaymentHistory insert(PaymentHistory history) {
        String sql = "INSERT INTO payment_history (payment_id, from_status, to_status, reason, " +
                     "triggered_by, created_at) VALUES (?, ?, ?, ?, ?, ?)";

        jdbcTemplate.update(sql,
            history.getPaymentId(),
            history.getFromStatus(),
            history.getToStatus(),
            history.getReason(),
            history.getTriggeredBy(),
            Timestamp.valueOf(LocalDateTime.now())
        );

        return history;
    }

    /**
     * 根据支付ID查询历史记录
     */
    public List<PaymentHistory> findByPaymentId(Long paymentId) {
        String sql = "SELECT * FROM payment_history WHERE payment_id = ? ORDER BY created_at ASC";
        return jdbcTemplate.query(sql, new Object[]{paymentId}, HISTORY_ROW_MAPPER);
    }

    /**
     * 查询特定支付的最后一条历史记录
     */
    public PaymentHistory findLatestByPaymentId(Long paymentId) {
        String sql = "SELECT * FROM payment_history WHERE payment_id = ? ORDER BY created_at DESC LIMIT 1";
        List<PaymentHistory> results = jdbcTemplate.query(sql, new Object[]{paymentId}, HISTORY_ROW_MAPPER);
        return results.isEmpty() ? null : results.get(0);
    }
}

package com.team.payment.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import jakarta.validation.constraints.*;
import java.math.BigDecimal;

/**
 * 创建支付请求DTO
 * 成员A负责实现
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class CreatePaymentRequest {

    /** 付款账户 */
    @NotBlank(message = "sourceAccount 不能为空")
    @Size(min = 1, max = 50, message = "sourceAccount 长度应为1-50")
    private String sourceAccount;

    /** 收款账户 */
    @NotBlank(message = "destinationAccount 不能为空")
    @Size(min = 1, max = 50, message = "destinationAccount 长度应为1-50")
    private String destinationAccount;

    /** 金额 */
    @NotNull(message = "amount 不能为null")
    @DecimalMin(value = "0.01", message = "amount 必须大于0")
    @Digits(integer = 16, fraction = 2, message = "amount 最多2位小数")
    private BigDecimal amount;

    /** 币种 */
    private String currency;

    /** 参考号/备注 */
    @Size(max = 255, message = "reference 长度最多255")
    private String reference;
}

