package com.team.payment.scheduler;

import com.team.payment.dao.PaymentDao;
import com.team.payment.dao.PaymentHistoryDao;
import com.team.payment.entity.Payment;
import com.team.payment.entity.PaymentHistory;
import com.team.payment.statemachine.PaymentStateMachine;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Random;

/**
 * 支付超时检测调度器
 * 每分钟执行一次，检测超过15分钟未更新的支付，自动推进状态
 * 成员D负责实现
 */
@Component
public class PaymentTimeoutScheduler {

    @Autowired
    private PaymentDao paymentDao;

    @Autowired
    private PaymentHistoryDao paymentHistoryDao;

    @Value("${payment.scheduler.enabled:true}")
    private boolean schedulerEnabled;

    @Value("${payment.scheduler.timeout-minutes:15}")
    private int timeoutMinutes;

    @Value("${payment.scheduler.failure-rate:0.1}")
    private double failureRate;

    private static final Random random = new Random();

    /**
     * 定时任务：每60秒执行一次超时检测
     */
    @Scheduled(fixedRateString = "${payment.scheduler.execution-interval-seconds:60}", 
               timeUnit = java.util.concurrent.TimeUnit.SECONDS)
    @Transactional
    public void checkAndProcessTimeouts() {
        if (!schedulerEnabled) {
            return;
        }

        try {
            // 1. 处理CREATED -> VALIDATED
            processCREATEDToVALIDATED();

            // 2. 处理VALIDATED -> SENT
            processVALIDATEDToSENT();

            // 3. 处理SENT -> COMPLETED/FAILED
            processSENTToCompletion();
        } catch (Exception e) {
            System.err.println("PaymentTimeoutScheduler caught exception: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * 处理 CREATED -> VALIDATED 转移
     */
    private void processCREATEDToVALIDATED() {
        List<Payment> payments = paymentDao.findTimeoutPayments("CREATED", timeoutMinutes);

        for (Payment payment : payments) {
            try {
                if (PaymentStateMachine.isValidTransition(payment.getStatus(), "VALIDATED")) {
                    paymentDao.updateStatus(payment.getId(), "VALIDATED", null, null);

                    PaymentHistory history = PaymentHistory.builder()
                        .paymentId(payment.getId())
                        .fromStatus("CREATED")
                        .toStatus("VALIDATED")
                        .reason("Timeout after " + timeoutMinutes + " minutes")
                        .triggeredBy("SCHEDULER")
                        .build();
                    paymentHistoryDao.insert(history);

                    System.out.println("Payment " + payment.getId() + " transitioned CREATED -> VALIDATED");
                }
            } catch (Exception e) {
                System.err.println("Error processing payment " + payment.getId() + ": " + e.getMessage());
            }
        }
    }

    /**
     * 处理 VALIDATED -> SENT 转移
     */
    private void processVALIDATEDToSENT() {
        List<Payment> payments = paymentDao.findTimeoutPayments("VALIDATED", timeoutMinutes);

        for (Payment payment : payments) {
            try {
                if (PaymentStateMachine.isValidTransition(payment.getStatus(), "SENT")) {
                    paymentDao.updateStatus(payment.getId(), "SENT", null, null);

                    PaymentHistory history = PaymentHistory.builder()
                        .paymentId(payment.getId())
                        .fromStatus("VALIDATED")
                        .toStatus("SENT")
                        .reason("Timeout after " + timeoutMinutes + " minutes")
                        .triggeredBy("SCHEDULER")
                        .build();
                    paymentHistoryDao.insert(history);

                    System.out.println("Payment " + payment.getId() + " transitioned VALIDATED -> SENT");
                }
            } catch (Exception e) {
                System.err.println("Error processing payment " + payment.getId() + ": " + e.getMessage());
            }
        }
    }

    /**
     * 处理 SENT -> COMPLETED/FAILED 转移
     * 根据failureRate随机决定成功或失败
     */
    private void processSENTToCompletion() {
        List<Payment> payments = paymentDao.findTimeoutPayments("SENT", timeoutMinutes);

        for (Payment payment : payments) {
            try {
                boolean shouldFail = random.nextDouble() < failureRate;
                String nextStatus = shouldFail ? "FAILED" : "COMPLETED";
                String errorCode = shouldFail ? "NETWORK_TIMEOUT" : null;
                String errorMessage = shouldFail ? "Payment processing timeout" : null;

                if (PaymentStateMachine.isValidTransition(payment.getStatus(), nextStatus)) {
                    paymentDao.updateStatus(payment.getId(), nextStatus, errorCode, errorMessage);

                    PaymentHistory history = PaymentHistory.builder()
                        .paymentId(payment.getId())
                        .fromStatus("SENT")
                        .toStatus(nextStatus)
                        .reason("Timeout after " + timeoutMinutes + " minutes")
                        .triggeredBy("SCHEDULER")
                        .build();
                    paymentHistoryDao.insert(history);

                    String logMsg = String.format("Payment %d transitioned SENT -> %s", 
                        payment.getId(), nextStatus);
                    System.out.println(logMsg);
                }
            } catch (Exception e) {
                System.err.println("Error processing payment " + payment.getId() + ": " + e.getMessage());
            }
        }
    }
}

package com.team.payment.service;

