package com.team.payment.service;

import com.team.payment.dto.CreatePaymentRequest;
import com.team.payment.dto.HistoryResponse;
import com.team.payment.dto.PaymentListResponse;
import com.team.payment.dto.PaymentResponse;
import com.team.payment.entity.Payment;
import com.team.payment.entity.PaymentHistory;
import com.team.payment.exception.*;
import com.team.payment.dao.PaymentDao;
import com.team.payment.dao.PaymentHistoryDao;
import com.team.payment.statemachine.PaymentStateMachine;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.List;
import java.util.stream.Collectors;

/**
 * 支付业务服务实现
 * 主要包含：创建支付、参数校验、幂等性检查、状态管理等
 */
@Service
public class PaymentServiceImpl implements PaymentService {

    @Autowired
    private PaymentDao paymentDao;

    @Autowired
    private PaymentHistoryDao paymentHistoryDao;

    /**
     * 创建支付（成员A负责）
     * - 参数校验
     * - 幂等键检查
     * - 创建新支付记录
     */
    @Override
    @Transactional
    public PaymentResponse createPayment(CreatePaymentRequest request, String idempotencyKey) {
        // 1. 参数校验
        validateCreatePaymentRequest(request);

        // 2. 幂等键检查
        Payment existingPayment = paymentDao.findByIdempotencyKey(idempotencyKey);
        if (existingPayment != null) {
            // 检查内容是否一致
            if (isPaymentContentEqual(existingPayment, request)) {
                return convertToResponse(existingPayment);
            } else {
                // 内容不一致，返回冲突
                throw new PaymentException("DUPLICATE_IDEMPOTENCY_KEY", 
                    "Idempotency-Key重复但内容不同");
            }
        }

        // 3. 创建新支付记录（初始状态为CREATED）
        Payment payment = Payment.builder()
            .idempotencyKey(idempotencyKey)
            .sourceAccount(request.getSourceAccount())
            .destinationAccount(request.getDestinationAccount())
            .amount(request.getAmount())
            .currency(request.getCurrency() != null ? request.getCurrency() : "CNY")
            .status("CREATED")
            .reference(request.getReference())
            .version(0L)
            .build();

        payment = paymentDao.create(payment);

        // 4. 记录历史：null -> CREATED
        PaymentHistory history = PaymentHistory.builder()
            .paymentId(payment.getId())
            .fromStatus(null)
            .toStatus("CREATED")
            .reason("Payment created")
            .triggeredBy("API")
            .build();
        paymentHistoryDao.insert(history);

        return convertToResponse(payment);
    }

    /**
     * 根据ID查询支付详情（成员C负责）
     */
    @Override
    public PaymentResponse getPaymentDetail(Long paymentId) {
        Payment payment = paymentDao.findById(paymentId);
        if (payment == null) {
            throw new PaymentNotFoundException(paymentId);
        }
        return convertToResponse(payment);
    }

    /**
     * 分页查询支付列表（成员C负责）
     */
    @Override
    public PaymentListResponse listPayments(int page, int size, String status) {
        List<Payment> payments = paymentDao.findPaginated(page, size, status);
        long total = paymentDao.countByStatus(status);

        List<PaymentResponse> content = payments.stream()
            .map(this::convertToResponse)
            .collect(Collectors.toList());

        return PaymentListResponse.builder()
            .content(content)
            .totalElements(total)
            .totalPages((int) Math.ceil((double) total / size))
            .currentPage(page)
            .pageSize(size)
            .build();
    }

    /**
     * 查询支付历史（成员C负责）
     */
    @Override
    public List<HistoryResponse> getPaymentHistory(Long paymentId) {
        Payment payment = paymentDao.findById(paymentId);
        if (payment == null) {
            throw new PaymentNotFoundException(paymentId);
        }

        List<PaymentHistory> histories = paymentHistoryDao.findByPaymentId(paymentId);
        return histories.stream()
            .map(h -> HistoryResponse.builder()
                .fromStatus(h.getFromStatus())
                .toStatus(h.getToStatus())
                .reason(h.getReason())
                .triggeredBy(h.getTriggeredBy())
                .createdAt(h.getCreatedAt())
                .build())
            .collect(Collectors.toList());
    }

    /**
     * 手动推进为VALIDATED（成员B负责 - 演示用）
     */
    @Override
    @Transactional
    public PaymentResponse validatePayment(Long paymentId) {
        Payment payment = paymentDao.findById(paymentId);
        if (payment == null) {
            throw new PaymentNotFoundException(paymentId);
        }

        String currentStatus = payment.getStatus();
        String nextStatus = "VALIDATED";

        if (!PaymentStateMachine.isValidTransition(currentStatus, nextStatus)) {
            throw new InvalidStatusTransitionException(currentStatus, nextStatus);
        }

        paymentDao.updateStatus(paymentId, nextStatus, null, null);

        // 记录历史
        PaymentHistory history = PaymentHistory.builder()
            .paymentId(paymentId)
            .fromStatus(currentStatus)
            .toStatus(nextStatus)
            .reason("Manual validation via API")
            .triggeredBy("API")
            .build();
        paymentHistoryDao.insert(history);

        return convertToResponse(paymentDao.findById(paymentId));
    }

    /**
     * 手动推进为SENT（成员B负责 - 演示用）
     */
    @Override
    @Transactional
    public PaymentResponse sendPayment(Long paymentId) {
        Payment payment = paymentDao.findById(paymentId);
        if (payment == null) {
            throw new PaymentNotFoundException(paymentId);
        }

        String currentStatus = payment.getStatus();
        String nextStatus = "SENT";

        if (!PaymentStateMachine.isValidTransition(currentStatus, nextStatus)) {
            throw new InvalidStatusTransitionException(currentStatus, nextStatus);
        }

        paymentDao.updateStatus(paymentId, nextStatus, null, null);

        PaymentHistory history = PaymentHistory.builder()
            .paymentId(paymentId)
            .fromStatus(currentStatus)
            .toStatus(nextStatus)
            .reason("Manual send via API")
            .triggeredBy("API")
            .build();
        paymentHistoryDao.insert(history);

        return convertToResponse(paymentDao.findById(paymentId));
    }

    /**
     * 手动推进为COMPLETED（成员B负责 - 演示用）
     */
    @Override
    @Transactional
    public PaymentResponse completePayment(Long paymentId) {
        Payment payment = paymentDao.findById(paymentId);
        if (payment == null) {
            throw new PaymentNotFoundException(paymentId);
        }

        String currentStatus = payment.getStatus();
        String nextStatus = "COMPLETED";

        if (!PaymentStateMachine.isValidTransition(currentStatus, nextStatus)) {
            throw new InvalidStatusTransitionException(currentStatus, nextStatus);
        }

        paymentDao.updateStatus(paymentId, nextStatus, null, null);

        PaymentHistory history = PaymentHistory.builder()
            .paymentId(paymentId)
            .fromStatus(currentStatus)
            .toStatus(nextStatus)
            .reason("Manual completion via API")
            .triggeredBy("API")
            .build();
        paymentHistoryDao.insert(history);

        return convertToResponse(paymentDao.findById(paymentId));
    }

    /**
     * 手动推进为FAILED（成员B负责 - 演示用）
     */
    @Override
    @Transactional
    public PaymentResponse failPayment(Long paymentId, String errorCode, String errorMessage) {
        Payment payment = paymentDao.findById(paymentId);
        if (payment == null) {
            throw new PaymentNotFoundException(paymentId);
        }

        String currentStatus = payment.getStatus();
        String nextStatus = "FAILED";

        if (!PaymentStateMachine.isValidTransition(currentStatus, nextStatus)) {
            throw new InvalidStatusTransitionException(currentStatus, nextStatus);
        }

        paymentDao.updateStatus(paymentId, nextStatus, errorCode, errorMessage);

        PaymentHistory history = PaymentHistory.builder()
            .paymentId(paymentId)
            .fromStatus(currentStatus)
            .toStatus(nextStatus)
            .reason("Manual failure via API: " + (errorMessage != null ? errorMessage : ""))
            .triggeredBy("API")
            .build();
        paymentHistoryDao.insert(history);

        return convertToResponse(paymentDao.findById(paymentId));
    }

    /**
     * 验证创建支付请求
     */
    private void validateCreatePaymentRequest(CreatePaymentRequest request) {
        // 检查金额
        if (request.getAmount() == null || request.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            throw new ValidationException("INVALID_AMOUNT", "金额必须大于0");
        }

        // 检查币种
        String currency = request.getCurrency() != null ? request.getCurrency() : "CNY";
        if (!"CNY".equals(currency)) {
            throw new ValidationException("INVALID_CURRENCY", "仅支持CNY币种");
        }

        // 检查账户
        if (request.getSourceAccount() != null && 
            request.getDestinationAccount() != null &&
            request.getSourceAccount().equals(request.getDestinationAccount())) {
            throw new ValidationException("INVALID_ACCOUNT", "源账户和目标账户不能相同");
        }
    }

    /**
     * 检查支付内容是否一致
     */
    private boolean isPaymentContentEqual(Payment payment, CreatePaymentRequest request) {
        return payment.getSourceAccount().equals(request.getSourceAccount()) &&
               payment.getDestinationAccount().equals(request.getDestinationAccount()) &&
               payment.getAmount().compareTo(request.getAmount()) == 0 &&
               (request.getCurrency() == null || 
                "CNY".equals(request.getCurrency()) ||
                payment.getCurrency().equals(request.getCurrency()));
    }

    /**
     * 将Payment实体转换为PaymentResponse
     */
    private PaymentResponse convertToResponse(Payment payment) {
        return PaymentResponse.builder()
            .id(payment.getId())
            .idempotencyKey(payment.getIdempotencyKey())
            .sourceAccount(payment.getSourceAccount())
            .destinationAccount(payment.getDestinationAccount())
            .amount(payment.getAmount())
            .currency(payment.getCurrency())
            .status(payment.getStatus())
            .errorCode(payment.getErrorCode())
            .errorMessage(payment.getErrorMessage())
            .reference(payment.getReference())
            .createdAt(payment.getCreatedAt())
            .updatedAt(payment.getUpdatedAt())
            .build();
    }
}

package com.team.payment.statemachine;

import com.team.payment.exception.InvalidStatusTransitionException;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * 支付状态机
 * 定义合法的状态转移
 * 成员B负责实现
 */
public class PaymentStateMachine {

    /**
     * 定义所有合法的状态转移
     */
    static class Transition {
        final String from;
        final String to;

        Transition(String from, String to) {
            this.from = from;
            this.to = to;
        }

        @Override
        public boolean equals(Object o) {
            if (!(o instanceof Transition)) return false;
            Transition t = (Transition) o;
            return from.equals(t.from) && to.equals(t.to);
        }

        @Override
        public int hashCode() {
            return (from + "->" + to).hashCode();
        }
    }

    private static final Set<Transition> VALID_TRANSITIONS = new HashSet<>(Arrays.asList(
        new Transition("CREATED", "VALIDATED"),
        new Transition("CREATED", "FAILED"),
        new Transition("VALIDATED", "SENT"),
        new Transition("VALIDATED", "FAILED"),
        new Transition("SENT", "COMPLETED"),
        new Transition("SENT", "FAILED")
    ));

    private static final Set<String> FINAL_STATES = new HashSet<>(Arrays.asList(
        "COMPLETED",
        "FAILED"
    ));

    /**
     * 检查状态转移是否合法
     */
    public static boolean isValidTransition(String fromStatus, String toStatus) {
        return VALID_TRANSITIONS.contains(new Transition(fromStatus, toStatus));
    }

    /**
     * 检查状态是否为终态
     */
    public static boolean isFinalStatus(String status) {
        return FINAL_STATES.contains(status);
    }

    /**
     * 获取所有合法的下一状态
     */
    public static Set<String> getValidNextStates(String currentStatus) {
        Set<String> nextStates = new HashSet<>();
        for (Transition t : VALID_TRANSITIONS) {
            if (t.from.equals(currentStatus)) {
                nextStates.add(t.to);
            }
        }
        return nextStates;
    }
}

-- MySQL 数据库初始化脚本 -- 创建支付处理系统数据库
-- 创建数据库 CREATE DATABASE IF NOT EXISTS payment_db DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE payment_db;
-- 支付主表 DROP TABLE IF EXISTS payment_history; DROP TABLE IF EXISTS payments;
CREATE TABLE payments ( id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '系统生成的唯一ID', idempotency_key VARCHAR(64) NOT NULL UNIQUE COMMENT '幂等键（客户端提供，唯一）', source_account VARCHAR(50) NOT NULL COMMENT '付款账户', destination_account VARCHAR(50) NOT NULL COMMENT '收款账户', amount DECIMAL(18, 2) NOT NULL COMMENT '金额（2位小数）', currency VARCHAR(3) NOT NULL DEFAULT 'CNY' COMMENT '币种（仅支持CNY）', status VARCHAR(20) NOT NULL DEFAULT 'CREATED' COMMENT '当前状态', error_code VARCHAR(50) NULL COMMENT '失败错误码', error_message VARCHAR(255) NULL COMMENT '失败错误信息', reference VARCHAR(255) NULL COMMENT '参考号/备注', version BIGINT NOT NULL DEFAULT 0 COMMENT '版本号（乐观锁）', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
CONSTRAINT chk_amount CHECK (amount > 0), CONSTRAINT chk_accounts_diff CHECK (source_account <> destination_account), INDEX idx_status (status), INDEX idx_created_at (created_at), INDEX idx_updated_at (updated_at), INDEX idx_idempotency_key (idempotency_key) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='支付记录表';
-- 状态历史表 CREATE TABLE payment_history ( id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '自增ID', payment_id BIGINT NOT NULL COMMENT '关联支付ID', from_status VARCHAR(20) NULL COMMENT '变更前状态', to_status VARCHAR(20) NOT NULL COMMENT '变更后状态', reason VARCHAR(255) NULL COMMENT '变更原因', triggered_by VARCHAR(50) NOT NULL COMMENT '触发方（API/SCHEDULER/SYSTEM）', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录时间',
CONSTRAINT fk_history_payment FOREIGN KEY (payment_id) REFERENCES payments(id) ON DELETE CASCADE, INDEX idx_payment_id (payment_id), INDEX idx_created_at (created_at) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='支付历史记录表';
