    }
}

/* ===== 加载动画 ===== */
@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

.loading-spinner {
    display: inline-block;
    width: 20px;
    height: 20px;
    border: 3px solid #f3f3f3;
    border-top: 3px solid #667eea;
    border-radius: 50%;
    animation: spin 1s linear infinite;
}

/* ===== 弹出提示 ===== */
.alert {
    padding: 15px;
    margin-bottom: 20px;
    border-radius: 5px;
    border-left: 4px solid #667eea;
}

.alert.alert-success {
    background: #d4edda;
    color: #155724;
    border-left-color: #28a745;
}

.alert.alert-error {
    background: #f8d7da;
    color: #721c24;
    border-left-color: #dc3545;
}

.alert.alert-info {
    background: #d1ecf1;
    color: #0c5460;
    border-left-color: #17a2b8;
}

/**
 * API 请求模块
 * 封装所有后端API调用
 */

const API_BASE_URL = '/api/payments';

class PaymentAPI {
    /**
     * 创建支付
     */
    static async createPayment(data, idempotencyKey) {
        const response = await fetch(API_BASE_URL, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Idempotency-Key': idempotencyKey
            },
            body: JSON.stringify(data)
        });

        if (response.status === 201 || response.status === 200) {
            return { code: 'SUCCESS', data: await response.json(), status: response.status };
        } else if (response.status === 409) {
            return { code: 'CONFLICT', data: await response.json(), status: response.status };
        } else {
            const error = await response.json();
            return { code: 'ERROR', data: error, status: response.status };
        }
    }

    /**
     * 获取支付详情
     */
    static async getPaymentDetail(paymentId) {
        const response = await fetch(`${API_BASE_URL}/${paymentId}`, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            }
        });

        if (response.ok) {
            return { code: 'SUCCESS', data: await response.json() };
        } else {
            const error = await response.json();
            return { code: 'ERROR', data: error, status: response.status };
        }
    }

    /**
     * 获取支付列表
     */
    static async listPayments(page = 0, size = 20, status = null) {
        let url = `${API_BASE_URL}?page=${page}&size=${size}`;
        if (status && status !== '') {
            url += `&status=${status}`;
        }

        const response = await fetch(url, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            }
        });

        if (response.ok) {
            return { code: 'SUCCESS', data: await response.json() };
        } else {
            const error = await response.json();
            return { code: 'ERROR', data: error };
        }
    }

    /**
     * 获取支付历史
     */
    static async getPaymentHistory(paymentId) {
        const response = await fetch(`${API_BASE_URL}/${paymentId}/history`, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/json'
            }
        });

        if (response.ok) {
            return { code: 'SUCCESS', data: await response.json() };
        } else {
            const error = await response.json();
            return { code: 'ERROR', data: error };
        }
    }

    /**
     * 验证支付
     */
    static async validatePayment(paymentId) {
        return this._updatePaymentStatus(paymentId, 'validate');
    }

    /**
     * 发送支付
     */
    static async sendPayment(paymentId) {
        return this._updatePaymentStatus(paymentId, 'send');
    }

    /**
     * 完成支付
     */
    static async completePayment(paymentId) {
        return this._updatePaymentStatus(paymentId, 'complete');
    }

    /**
     * 失败支付
     */
    static async failPayment(paymentId, errorCode = 'MANUAL_FAILURE', errorMessage = '手动标记为失败') {
        const response = await fetch(`${API_BASE_URL}/${paymentId}/fail?errorCode=${errorCode}&errorMessage=${encodeURIComponent(errorMessage)}`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            }
        });

        if (response.ok) {
            return { code: 'SUCCESS', data: await response.json() };
        } else {
            const error = await response.json();
            return { code: 'ERROR', data: error, status: response.status };
        }
    }

    /**
     * 通用的状态更新方法
     */
    static async _updatePaymentStatus(paymentId, action) {
        const response = await fetch(`${API_BASE_URL}/${paymentId}/${action}`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            }
        });

        if (response.ok) {
            return { code: 'SUCCESS', data: await response.json() };
        } else {
            const error = await response.json();
            return { code: 'ERROR', data: error, status: response.status };
        }
    }
}

/**
 * 主业务逻辑模块
 * 处理页面交互和API调用
 */

let currentPage = 0;
let currentPageSize = 20;
let currentStatus = '';

/**
 * 页面初始化
 */
document.addEventListener('DOMContentLoaded', function () {
    initPageEvents();
    showModule('create');
    generateIdempotencyKey();
});

/**
 * 初始化页面事件
 */
function initPageEvents() {
    // 导航菜单
    document.querySelectorAll('nav a').forEach(link => {
        link.addEventListener('click', function (e) {
            e.preventDefault();
            const target = this.getAttribute('href');
            showModule(target.substring(1));
        });
    });

    // 创建支付表单
    document.getElementById('createForm').addEventListener('submit', handleCreatePayment);
    document.getElementById('generateKeyBtn').addEventListener('click', generateIdempotencyKey);

    // 列表查询
    document.getElementById('queryBtn').addEventListener('click', handleListPayments);
    document.getElementById('statusFilter').addEventListener('change', () => {
        currentPage = 0;
        handleListPayments();
    });
    document.getElementById('pageSize').addEventListener('change', () => {
        currentPage = 0;
        handleListPayments();
    });

    // 详情查询
    document.getElementById('detailQueryBtn').addEventListener('click', handleGetDetail);
    document.getElementById('detailPaymentId').addEventListener('keypress', function (e) {
        if (e.key === 'Enter') {
            handleGetDetail();
        }
    });
}

/**
 * 模块切换
 */
function showModule(moduleName) {
    document.querySelectorAll('.module').forEach(m => m.classList.remove('active'));
    const targetModule = document.getElementById(moduleName);
    if (targetModule) {
        targetModule.classList.add('active');
    }

    document.querySelectorAll('nav a').forEach(a => a.classList.remove('active'));
    document.querySelector(`nav a[href="#${moduleName}"]`)?.classList.add('active');
}

/**
 * 生成幂等键
 */
function generateIdempotencyKey() {
    const timestamp = Date.now();
    const random = Math.random().toString(36).substring(2, 9);
    const key = `payment-${timestamp}-${random}`;
    document.getElementById('idempotencyKey').value = key;
}

/**
 * 处理创建支付
 */
async function handleCreatePayment(e) {
    e.preventDefault();

    const sourceAccount = document.getElementById('sourceAccount').value.trim();
    const destinationAccount = document.getElementById('destinationAccount').value.trim();
    const amount = document.getElementById('amount').value.trim();
    const currency = 'CNY';
    const reference = document.getElementById('reference').value.trim();
    const idempotencyKey = document.getElementById('idempotencyKey').value.trim();

    if (!sourceAccount || !destinationAccount || !amount) {
        showResult('createResult', '请填写所有必需字段', 'error');
        return;
    }

    const paymentData = {
        sourceAccount,
        destinationAccount,
        amount: parseFloat(amount),
        currency,
        reference: reference || undefined
    };

    const result = await PaymentAPI.createPayment(paymentData, idempotencyKey);

    if (result.code === 'SUCCESS') {
        const isNew = result.status === 201;
        const message = isNew 
            ? `✓ 支付创建成功! ID: ${result.data.id}`
            : `✓ 重复请求，返回已存在的支付! ID: ${result.data.id}`;

        showResult('createResult', message, 'success');
        showPaymentDetail(result.data);

        // 重置表单
        document.getElementById('createForm').reset();
        generateIdempotencyKey();
    } else if (result.code === 'CONFLICT') {
        showResult('createResult', `✗ 幂等键冲突: ${result.data.message}`, 'error');
    } else {
        showResult('createResult', `✗ 创建失败: ${result.data.message}`, 'error');
    }
}

/**
 * 处理列表查询
 */
async function handleListPayments() {
    const statusFilter = document.getElementById('statusFilter').value;
    const pageSizeSelect = document.getElementById('pageSize').value;
    currentPageSize = parseInt(pageSizeSelect);
    currentStatus = statusFilter;

    const result = await PaymentAPI.listPayments(currentPage, currentPageSize, statusFilter);

    if (result.code === 'SUCCESS') {
        renderPaymentTable(result.data.content);
        renderPagination(result.data.totalPages, currentPage);
    } else {
        showAlert('paymentTable', `查询失败: ${result.data.message}`, 'error');
    }
}

/**
 * 渲染支付表格
 */
function renderPaymentTable(payments) {
    const tbody = document.querySelector('#paymentTable tbody');
    tbody.innerHTML = '';

    if (!payments || payments.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="loading">暂无数据</td></tr>';
        return;
    }

    payments.forEach(payment => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${payment.id}</td>
            <td>${payment.idempotencyKey}</td>
            <td>${payment.sourceAccount}</td>
            <td>${payment.destinationAccount}</td>
            <td>${payment.amount}</td>
            <td><span class="status ${payment.status}">${getStatusLabel(payment.status)}</span></td>
            <td>${formatDateTime(payment.createdAt)}</td>
            <td>
                <button class="btn btn-outline" onclick="loadPaymentDetail(${payment.id})">详情</button>
            </td>
        `;
        tbody.appendChild(row);
    });
}

/**
 * 渲染分页
 */
function renderPagination(totalPages, currentPage) {
    const paginationDiv = document.getElementById('pagination');
    paginationDiv.innerHTML = '';

    if (totalPages <= 1) return;

    // 上一页
    if (currentPage > 0) {
        const prevBtn = document.createElement('button');
        prevBtn.textContent = '上一页';
        prevBtn.onclick = () => {
            currentPage--;
            handleListPayments();
        };
        paginationDiv.appendChild(prevBtn);
    }

    // 页码
    for (let i = 0; i < totalPages; i++) {
        const pageBtn = document.createElement('button');
        pageBtn.textContent = (i + 1).toString();
        if (i === currentPage) {
            pageBtn.classList.add('active');
        }
        pageBtn.onclick = () => {
            currentPage = i;
            handleListPayments();
        };
        paginationDiv.appendChild(pageBtn);
    }

    // 下一页
    if (currentPage < totalPages - 1) {
        const nextBtn = document.createElement('button');
        nextBtn.textContent = '下一页';
        nextBtn.onclick = () => {
            currentPage++;
            handleListPayments();
        };
        paginationDiv.appendChild(nextBtn);
    }
}

/**
 * 处理详情查询
 */
async function handleGetDetail() {
    const paymentIdInput = document.getElementById('detailPaymentId');
    const paymentId = parseInt(paymentIdInput.value.trim());

    if (!paymentId) {
        showAlert('detailContent', '请输入支付ID', 'error');
        return;
    }

    await loadPaymentDetail(paymentId);
}

/**
 * 加载支付详情
 */
async function loadPaymentDetail(paymentId) {
    const result = await PaymentAPI.getPaymentDetail(paymentId);

    if (result.code === 'SUCCESS') {
        showPaymentDetail(result.data);
        showModule('detail');
        document.getElementById('detailPaymentId').value = paymentId;

        // 加载历史记录
        const historyResult = await PaymentAPI.getPaymentHistory(paymentId);
        if (historyResult.code === 'SUCCESS') {
            renderPaymentHistory(historyResult.data);
        }

        // 显示操作按钮
        renderOperationButtons(result.data);
    } else {
        showAlert('detailContent', `查询失败: ${result.data.message}`, 'error');
    }
}

/**
 * 显示支付详情
 */
function showPaymentDetail(payment) {
    const detailContent = document.getElementById('detailContent');
    detailContent.innerHTML = `
        <div class="detail-content">
            <div class="detail-item">
                <span class="detail-label">支付ID:</span>
                <span class="detail-value">${payment.id}</span>
            </div>
            <div class="detail-item">
                <span class="detail-label">幂等键:</span>
                <span class="detail-value">${payment.idempotencyKey}</span>
            </div>
            <div class="detail-item">
                <span class="detail-label">付款账户:</span>
                <span class="detail-value">${payment.sourceAccount}</span>
            </div>
            <div class="detail-item">
                <span class="detail-label">收款账户:</span>
                <span class="detail-value">${payment.destinationAccount}</span>
            </div>
            <div class="detail-item">
                <span class="detail-label">金额:</span>
                <span class="detail-value">${payment.amount} ${payment.currency}</span>
            </div>
            <div class="detail-item">
                <span class="detail-label">状态:</span>
                <span class="detail-value"><span class="status ${payment.status}">${getStatusLabel(payment.status)}</span></span>
            </div>
            ${payment.errorCode ? `
            <div class="detail-item">
                <span class="detail-label">错误码:</span>
                <span class="detail-value">${payment.errorCode}</span>
            </div>
            <div class="detail-item">
                <span class="detail-label">错误信息:</span>
                <span class="detail-value">${payment.errorMessage}</span>
            </div>
            ` : ''}
            <div class="detail-item">
                <span class="detail-label">参考号:</span>
                <span class="detail-value">${payment.reference || '-'}</span>
            </div>
            <div class="detail-item">
                <span class="detail-label">创建时间:</span>
                <span class="detail-value">${formatDateTime(payment.createdAt)}</span>
            </div>
            <div class="detail-item">
                <span class="detail-label">更新时间:</span>
                <span class="detail-value">${formatDateTime(payment.updatedAt)}</span>
            </div>
        </div>
    `;
}

/**
 * 渲染支付历史
 */
function renderPaymentHistory(histories) {
    const historySection = document.getElementById('historySection');
    const timeline = document.getElementById('historyTimeline');

    timeline.innerHTML = '';

    if (!histories || histories.length === 0) {
        historySection.style.display = 'none';
        return;
    }

    historySection.style.display = 'block';

    histories.forEach(record => {
        const item = document.createElement('div');
        item.className = 'timeline-item';
        item.innerHTML = `
            <div class="timeline-item-time">${formatDateTime(record.createdAt)}</div>
            <div class="timeline-item-status">
                ${record.fromStatus || '初始'} → ${record.toStatus}
            </div>
            <div class="timeline-item-reason">${record.reason || '-'}</div>
            <div class="timeline-item-triggered">触发方: ${record.triggeredBy}</div>
        `;
        timeline.appendChild(item);
    });
}

/**
 * 渲染操作按钮
 */
function renderOperationButtons(payment) {
    const operationsSection = document.getElementById('operationsSection');
    const operationButtons = document.getElementById('operationButtons');

    operationButtons.innerHTML = '';

    const buttons = [];

    // 根据当前状态显示可用的操作按钮
    if (payment.status === 'CREATED') {
        buttons.push({
            label: 'CREATED → VALIDATED',
            action: () => updatePaymentStatus(payment.id, 'validatePayment')
        });
    }

    if (payment.status === 'VALIDATED') {
        buttons.push({
            label: 'VALIDATED → SENT',
            action: () => updatePaymentStatus(payment.id, 'sendPayment')
        });
    }

    if (payment.status === 'SENT') {
        buttons.push({
            label: 'SENT → COMPLETED',
            action: () => updatePaymentStatus(payment.id, 'completePayment')
        });
        buttons.push({
            label: 'SENT → FAILED',
            action: () => updatePaymentStatus(payment.id, 'failPayment')
        });
    }

    // 如果还不是终态，允许直接标记为失败
    if (payment.status !== 'COMPLETED' && payment.status !== 'FAILED') {
        buttons.push({
            label: '标记为失败',
            action: () => updatePaymentStatus(payment.id, 'failPayment'),
            className: 'btn-danger'
        });
    }

    // 刷新按钮
    buttons.push({
        label: '刷新',
        action: () => loadPaymentDetail(payment.id)
    });

    buttons.forEach(btn => {
        const button = document.createElement('button');
        button.className = `btn ${btn.className || 'btn-primary'} operation-btn`;
        button.textContent = btn.label;
        button.onclick = btn.action;
        operationButtons.appendChild(button);
    });

    if (buttons.length > 0) {
        operationsSection.style.display = 'block';
    }
}

/**
 * 更新支付状态
 */
async function updatePaymentStatus(paymentId, action) {
    let result;

    switch (action) {
        case 'validatePayment':
            result = await PaymentAPI.validatePayment(paymentId);
            break;
        case 'sendPayment':
            result = await PaymentAPI.sendPayment(paymentId);
            break;
        case 'completePayment':
            result = await PaymentAPI.completePayment(paymentId);
            break;
        case 'failPayment':
            result = await PaymentAPI.failPayment(paymentId);
            break;
        default:
            return;
    }

    if (result.code === 'SUCCESS') {
        showAlert('detailContent', '✓ 状态更新成功', 'success');
        await loadPaymentDetail(paymentId);
    } else {
        showAlert('detailContent', `✗ 更新失败: ${result.data.message}`, 'error');
    }
}

/**
 * 显示提示信息
 */
function showResult(elementId, message, type) {
    const resultDiv = document.getElementById(elementId);
    resultDiv.textContent = message;
    resultDiv.className = `result show ${type}`;

    setTimeout(() => {
        resultDiv.classList.remove('show');
    }, 3000);
}

/**
 * 显示警告信息
 */
function showAlert(elementId, message, type) {
    const container = document.getElementById(elementId);
    if (container) {
        const alert = document.createElement('div');
        alert.className = `alert alert-${type}`;
        alert.textContent = message;
        container.insertBefore(alert, container.firstChild);

        setTimeout(() => {
            alert.remove();
        }, 5000);
    }
}

/**
 * 格式化日期时间
 */
function formatDateTime(dateTimeStr) {
    if (!dateTimeStr) return '-';
    const date = new Date(dateTimeStr);
    return date.toLocaleString('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });
}

/**
 * 获取状态标签
 */
function getStatusLabel(status) {
    const labels = {
        'CREATED': '已创建',
        'VALIDATED': '已验证',
        'SENT': '已发送',
        'COMPLETED': '已完成',
        'FAILED': '失败'
    };
    return labels[status] || status;
}

package com.team.payment.controller;

import com.team.payment.dto.CreatePaymentRequest;
import com.team.payment.dto.PaymentResponse;
import com.team.payment.service.PaymentService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.mock.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/**
 * 支付控制器集成测试
 * 成员A负责创建接口测试
 * 成员B负责状态推进接口测试
 * 成员C负责查询接口测试
 */
@WebMvcTest(PaymentController.class)
public class PaymentControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private PaymentService paymentService;

    /**
     * P0: 创建支付 - 返回201 Created
     */
    @Test
    public void testCreatePayment_Success() throws Exception {
        CreatePaymentRequest request = CreatePaymentRequest.builder()
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("1500.50"))
            .currency("CNY")
            .reference("INV-20260727")
            .build();

        PaymentResponse response = PaymentResponse.builder()
            .id(1L)
            .idempotencyKey("key-001")
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("1500.50"))
            .currency("CNY")
            .status("CREATED")
            .createdAt(LocalDateTime.now())
            .updatedAt(LocalDateTime.now())
            .build();

        when(paymentService.createPayment(any(CreatePaymentRequest.class), eq("key-001")))
            .thenReturn(response);

        mockMvc.perform(post("/api/payments")
                .header("Idempotency-Key", "key-001")
                .contentType(MediaType.APPLICATION_JSON)
                .content("{\"sourceAccount\":\"ACC001\",\"destinationAccount\":\"ACC002\"," +
                         "\"amount\":1500.50,\"currency\":\"CNY\",\"reference\":\"INV-20260727\"}"))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.id").value(1))
            .andExpect(jsonPath("$.status").value("CREATED"));
    }

    /**
     * P0: 查询支付详情 - 返回200
     */
    @Test
    public void testGetPaymentDetail_Success() throws Exception {
        PaymentResponse response = PaymentResponse.builder()
            .id(1L)
            .idempotencyKey("key-001")
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("1500.50"))
            .currency("CNY")
            .status("CREATED")
            .createdAt(LocalDateTime.now())
            .updatedAt(LocalDateTime.now())
            .build();

        when(paymentService.getPaymentDetail(1L)).thenReturn(response);

        mockMvc.perform(get("/api/payments/1")
                .contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.id").value(1))
            .andExpect(jsonPath("$.status").value("CREATED"));
    }

    /**
     * P0: 查询支付详情 - 不存在返回404
     */
    @Test
    public void testGetPaymentDetail_NotFound() throws Exception {
        when(paymentService.getPaymentDetail(999L))
            .thenThrow(new RuntimeException("Payment not found"));

        mockMvc.perform(get("/api/payments/999")
                .contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isInternalServerError());
    }

    /**
     * P0: 列表查询 - 返回200
     */
    @Test
    public void testListPayments_Success() throws Exception {
        mockMvc.perform(get("/api/payments?status=CREATED&page=0&size=20")
                .contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isOk());
    }

    /**
     * P0: 状态推进 - CREATED -> VALIDATED
     */
    @Test
    public void testValidatePayment_Success() throws Exception {
        PaymentResponse response = PaymentResponse.builder()
            .id(1L)
            .status("VALIDATED")
            .createdAt(LocalDateTime.now())
            .updatedAt(LocalDateTime.now())
            .build();

        when(paymentService.validatePayment(1L)).thenReturn(response);

        mockMvc.perform(post("/api/payments/1/validate")
                .contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.status").value("VALIDATED"));
    }
}

package com.team.payment.service;

import com.team.payment.dao.PaymentDao;
import com.team.payment.dao.PaymentHistoryDao;
import com.team.payment.dto.CreatePaymentRequest;
import com.team.payment.dto.PaymentResponse;
import com.team.payment.entity.Payment;
import com.team.payment.exception.PaymentException;
import com.team.payment.exception.PaymentNotFoundException;
import com.team.payment.exception.ValidationException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.time.LocalDateTime;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/**
 * 支付服务单元测试
 * 成员A负责幂等性和创建相关测试
 * 成员B负责状态机相关测试
 * 成员C负责查询相关测试
 */
@ExtendWith(MockitoExtension.class)
public class PaymentServiceTest {

    @Mock
    private PaymentDao paymentDao;

    @Mock
    private PaymentHistoryDao paymentHistoryDao;

    @InjectMocks
    private PaymentServiceImpl paymentService;

    private CreatePaymentRequest validRequest;

    @BeforeEach
    public void setUp() {
        validRequest = CreatePaymentRequest.builder()
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("1500.50"))
            .currency("CNY")
            .reference("INV-20260727")
            .build();
    }

    // ===== 创建支付相关测试 =====

    /**
     * P0: 创建支付 - 正常路径
     */
    @Test
    public void testCreatePayment_Success() {
        when(paymentDao.findByIdempotencyKey("key-001")).thenReturn(null);
        when(paymentDao.create(any(Payment.class))).thenAnswer(invocation -> {
            Payment p = invocation.getArgument(0);
            p.setId(1L);
            p.setCreatedAt(LocalDateTime.now());
            p.setUpdatedAt(LocalDateTime.now());
            return p;
        });

        PaymentResponse response = paymentService.createPayment(validRequest, "key-001");

        assertNotNull(response);
        assertEquals(1L, response.getId());
        assertEquals("CREATED", response.getStatus());
        assertEquals("CNY", response.getCurrency());
        verify(paymentDao, times(1)).create(any(Payment.class));
        verify(paymentHistoryDao, times(1)).insert(any());
    }

    /**
     * P0: 幂等键重复 - 内容一致，返回200
     */
    @Test
    public void testCreatePayment_IdempotentKeyDuplicate_ContentMatch() {
        Payment existingPayment = Payment.builder()
            .id(1L)
            .idempotencyKey("key-001")
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("1500.50"))
            .currency("CNY")
            .status("CREATED")
            .createdAt(LocalDateTime.now())
            .updatedAt(LocalDateTime.now())
            .build();

        when(paymentDao.findByIdempotencyKey("key-001")).thenReturn(existingPayment);

        PaymentResponse response = paymentService.createPayment(validRequest, "key-001");

        assertNotNull(response);
        assertEquals(1L, response.getId());
        verify(paymentDao, never()).create(any(Payment.class));
    }

    /**
     * P0: 幂等键重复 - 内容不一致，返回409
     */
    @Test
    public void testCreatePayment_IdempotentKeyConflict() {
        Payment existingPayment = Payment.builder()
            .id(1L)
            .idempotencyKey("key-001")
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("999.99"))  // 不同的金额
            .currency("CNY")
            .status("CREATED")
            .build();

        when(paymentDao.findByIdempotencyKey("key-001")).thenReturn(existingPayment);

        assertThrows(PaymentException.class, () -> {
            paymentService.createPayment(validRequest, "key-001");
        });
    }

    /**
     * P0: 金额校验 - 金额≤0拒绝
     */
    @Test
    public void testCreatePayment_InvalidAmount_ZeroOrNegative() {
        CreatePaymentRequest invalidRequest = CreatePaymentRequest.builder()
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("0"))
            .currency("CNY")
            .build();

        assertThrows(ValidationException.class, () -> {
            paymentService.createPayment(invalidRequest, "key-001");
        });
    }

    /**
     * P0: 币种校验 - 非CNY拒绝
     */
    @Test
    public void testCreatePayment_InvalidCurrency() {
        CreatePaymentRequest invalidRequest = CreatePaymentRequest.builder()
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("1500.50"))
            .currency("USD")  // 非CNY
            .build();

        assertThrows(ValidationException.class, () -> {
            paymentService.createPayment(invalidRequest, "key-001");
        });
    }

    /**
     * P0: 账户校验 - 源目账户相同拒绝
     */
    @Test
    public void testCreatePayment_SameSourceAndDestinationAccount() {
        CreatePaymentRequest invalidRequest = CreatePaymentRequest.builder()
            .sourceAccount("ACC001")
            .destinationAccount("ACC001")  // 相同
            .amount(new BigDecimal("1500.50"))
            .currency("CNY")
            .build();

        assertThrows(ValidationException.class, () -> {
            paymentService.createPayment(invalidRequest, "key-001");
        });
    }

    // ===== 查询相关测试 =====

    /**
     * P0: 查询支付 - 存在返回200
     */
    @Test
    public void testGetPaymentDetail_Found() {
        Payment payment = Payment.builder()
            .id(1L)
            .idempotencyKey("key-001")
            .sourceAccount("ACC001")
            .destinationAccount("ACC002")
            .amount(new BigDecimal("1500.50"))
            .currency("CNY")
            .status("CREATED")
            .createdAt(LocalDateTime.now())
            .updatedAt(LocalDateTime.now())
            .build();

        when(paymentDao.findById(1L)).thenReturn(payment);

        PaymentResponse response = paymentService.getPaymentDetail(1L);

        assertNotNull(response);
        assertEquals(1L, response.getId());
        assertEquals("CREATED", response.getStatus());
    }

    /**
     * P0: 查询支付 - 不存在返回404
     */
    @Test
    public void testGetPaymentDetail_NotFound() {
        when(paymentDao.findById(999L)).thenReturn(null);

        assertThrows(PaymentNotFoundException.class, () -> {
            paymentService.getPaymentDetail(999L);
        });
    }

    // ===== 状态机相关测试 =====

    /**
     * P0: 状态迁移 - 合法迁移
     */
    @Test
    public void testValidatePayment_Success() {
        Payment payment = Payment.builder()
            .id(1L)
            .status("CREATED")
            .build();

        when(paymentDao.findById(1L)).thenReturn(payment);
        when(paymentDao.updateStatus(eq(1L), eq("VALIDATED"), any(), any())).thenReturn(1);
        when(paymentDao.findById(1L)).thenReturn(
            Payment.builder()
                .id(1L)
                .status("VALIDATED")
                .createdAt(LocalDateTime.now())
                .updatedAt(LocalDateTime.now())
                .build()
        );

        PaymentResponse response = paymentService.validatePayment(1L);

        assertEquals("VALIDATED", response.getStatus());
        verify(paymentDao, times(2)).findById(1L);
        verify(paymentDao, times(1)).updateStatus(eq(1L), eq("VALIDATED"), any(), any());
    }

    /**
     * P0: 状态迁移 - 非法迁移
     */
    @Test
    public void testValidatePayment_InvalidTransition() {
        Payment payment = Payment.builder()
            .id(1L)
            .status("COMPLETED")  // 已完成，不能再转移
            .build();

        when(paymentDao.findById(1L)).thenReturn(payment);

        assertThrows(Exception.class, () -> {
            paymentService.validatePayment(1L);
        });
    }
}
